import sys

def main():
    s = sys.stdin.read().split()[0]
    cnt = {}
    order = []
    for ch in s:
        if ch not in cnt:
            cnt[ch] = 0
            order.append(ch)
        cnt[ch] += 1
    res = []
    active = order
    while active:
        res.extend(active)
        nxt = []
        for ch in active:
            cnt[ch] -= 1
            if cnt[ch] > 0:
                nxt.append(ch)
        active = nxt
    print(''.join(res))

main()

