s = sys.stdin.read().split()[0]
order = []
for ch in s:
    if ch not in order:
        order.append(ch)
left = {ch: s.count(ch) for ch in order}
res = ''
while len(res) < len(s):
    for ch in order:
        if left[ch] > 0:
            res += ch
            left[ch] -= 1
print(res)

